    12	bool ag_vision_health_gate(const struct ag_vision_health_state *state,
    13	                           bool inference_ok, struct ag_vision_result *result)
    14	{
    15	  if (!inference_ok || state->error_active)
    16	    {
    17	      memset(result, 0, sizeof(*result));
    18	      return false;
    19	    }
    20	
    21	  return true;
