    23	
    24	enum ag_vision_health_transition ag_vision_health_update(
    25	  struct ag_vision_health_state *state, bool inference_ok)
    26	{
    27	  if (!state->error_active)
    28	    {
    29	      state->consecutive_successes = 0;
    30	      if (inference_ok)
    31	        {
    32	          state->consecutive_failures = 0;
    33	        }
    34	      else if (state->consecutive_failures < AG_VISION_FAILURE_LIMIT)
    35	        {
    36	          state->consecutive_failures++;
    37	          if (state->consecutive_failures == AG_VISION_FAILURE_LIMIT)
    38	            {
    39	              state->error_active = true;
    40	              return AG_VISION_HEALTH_ENTERED_ERROR;
    41	            }
    42	        }
    43	
    44	      return AG_VISION_HEALTH_NO_CHANGE;
    45	    }
    46	
    47	  state->consecutive_failures = 0;
    48	  if (!inference_ok)
    49	    {
    50	      state->consecutive_successes = 0;
    51	    }
    52	  else if (state->consecutive_successes < AG_VISION_RECOVERY_LIMIT)
    53	    {
    54	      state->consecutive_successes++;
    55	      if (state->consecutive_successes == AG_VISION_RECOVERY_LIMIT)
    56	        {
    57	          state->consecutive_successes = 0;
    58	          state->error_active = false;
    59	          return AG_VISION_HEALTH_RECOVERED;
    60	        }
    61	    }
    62	
    63	  return AG_VISION_HEALTH_NO_CHANGE;
    64	}
