     8	static bool ag_elapsed(uint64_t now, uint64_t since, uint64_t duration)
     9	{
    10	  return now >= since && now - since >= duration;
    11	}
    12	
    13	static void ag_shift_timestamp(uint64_t *timestamp, uint64_t duration)
    14	{
    15	  if (*timestamp == 0)
    16	    {
    17	      return;
    18	    }
    19	
    20	  if (duration > UINT64_MAX - *timestamp)
    21	    {
    22	      *timestamp = UINT64_MAX;
    23	    }
    24	  else
    25	    {
    26	      *timestamp += duration;
    27	    }
    28	}
