    47	
    48	static uint32_t ag_apply_command(struct ag_state *state,
    49	                                 enum ag_command command)
    50	{
    51	  uint32_t events = 0;
    52	
    53	  switch (command)
    54	    {
    55	      case AG_COMMAND_ACKNOWLEDGE:
    56	        state->awaiting_ack = false;
    57	        state->sedentary_alerted = false;
    58	        state->lock_sent = false;
    59	        events |= AG_EVENT_ACKNOWLEDGED;
    60	        break;
    61	
    62	      case AG_COMMAND_PAUSE:
    63	        if (!state->reminders_paused)
    64	          {
    65	            state->reminders_paused = true;
    66	            events |= AG_EVENT_REMINDERS_PAUSED;
    67	          }
    68	        break;
    69	
    70	      case AG_COMMAND_RESUME:
    71	        if (state->reminders_paused)
    72	          {
    73	            state->reminders_paused = false;
    74	            events |= AG_EVENT_REMINDERS_ACTIVE;
    75	          }
    76	        break;
    77	
    78	      case AG_COMMAND_PRIVACY_ON:
    79	        if (!state->privacy_enabled)
    80	          {
    81	            state->privacy_enabled = true;
    82	            events |= AG_EVENT_PRIVACY_ON;
    83	          }
    84	        break;
    85	
    86	      case AG_COMMAND_PRIVACY_OFF:
    87	        if (state->privacy_enabled)
    88	          {
    89	            state->privacy_enabled = false;
    90	            events |= AG_EVENT_PRIVACY_OFF;
    91	            if (state->privacy_blurred)
    92	              {
    93	                state->privacy_blurred = false;
    94	                events |= AG_EVENT_UNBLUR_SCREEN;
    95	              }
    96	          }
    97	        break;
    98	
    99	      case AG_COMMAND_BRIGHTNESS_UP:
   100	        events |= AG_EVENT_BRIGHTNESS_UP;
   101	        break;
   102	
   103	      case AG_COMMAND_BRIGHTNESS_DOWN:
   104	        events |= AG_EVENT_BRIGHTNESS_DOWN;
   105	        break;
   106	
   107	      default:
   108	        break;
   109	    }
   110	
   111	  return events;
   112	}
   113	
   114	uint32_t ag_step(struct ag_state *state, const struct ag_config *config,
   115	                 const struct ag_observation *observation)
   116	{
   117	  uint32_t events;
   118	  uint64_t now = observation->monotonic_ms;
   119	  bool has_face = observation->face_count > 0;
   120	
   121	  events = ag_apply_command(state, observation->command);
   122	
   123	  if (!observation->vision_valid)
   124	    {
   125	      if (!state->vision_paused)
   126	        {
   127	          state->vision_paused = true;
   128	          state->vision_paused_since_ms = now;
   129	        }
   130	
   131	      return events;
   132	    }
   133	
   134	  if (state->vision_paused)
   135	    {
   136	      uint64_t paused_ms = now >= state->vision_paused_since_ms ?
   137	        now - state->vision_paused_since_ms : 0;
   138	
   139	      ag_shift_timestamp(&state->presence_since_ms, paused_ms);
   140	      ag_shift_timestamp(&state->absence_since_ms, paused_ms);
   141	      ag_shift_timestamp(&state->poor_posture_since_ms, paused_ms);
   142	      ag_shift_timestamp(&state->awaiting_ack_since_ms, paused_ms);
   143	      state->vision_paused = false;
   144	      state->vision_paused_since_ms = 0;
   145	    }
   146	
   147	  /* Acknowledging a reminder starts a fresh sitting interval.  Without this
   148	   * reset the same observation could immediately raise a second alert. */
   149	
   150	  if (observation->command == AG_COMMAND_ACKNOWLEDGE && has_face)
   151	    {
   152	      state->presence_since_ms = now;
   153	    }
   154	
   155	  if (!state->initialized)
   156	    {
   157	      state->initialized = true;
   158	      state->present = has_face;
   159	      if (has_face)
   160	        {
   161	          state->presence_since_ms = now;
   162	          events |= AG_EVENT_PRESENCE_STARTED;
   163	        }
   164	      else
   165	        {
   166	          state->absence_since_ms = now;
   167	        }
   168	    }
   169	
   170	  if (has_face)
   171	    {
   172	      if (!state->present)
   173	        {
   174	          state->present = true;
   175	          state->presence_since_ms = now;
   176	          state->sedentary_alerted = false;
   177	          state->posture_alerted = false;
   178	          state->awaiting_ack = false;
   179	          state->lock_sent = false;
   180	          events |= AG_EVENT_PRESENCE_STARTED;
   181	        }
   182	
   183	      state->absence_since_ms = 0;
   184	
   185	      if (observation->posture_score >= config->posture_score_limit)
   186	        {
   187	          if (state->poor_posture_since_ms == 0)
   188	            {
   189	              state->poor_posture_since_ms = now;
   190	            }
   191	          else if (!state->posture_alerted && !state->reminders_paused &&
   192	                   ag_elapsed(now, state->poor_posture_since_ms,
   193	                              config->posture_hold_ms))
   194	            {
   195	              state->posture_alerted = true;
   196	              events |= AG_EVENT_POSTURE_ALERT;
   197	            }
   198	        }
   199	      else
   200	        {
   201	          state->poor_posture_since_ms = 0;
   202	          state->posture_alerted = false;
   203	        }
   204	
   205	      if (!state->reminders_paused && !state->sedentary_alerted &&
   206	          ag_elapsed(now, state->presence_since_ms, config->sedentary_ms))
   207	        {
   208	          state->sedentary_alerted = true;
   209	          state->awaiting_ack = true;
   210	          state->awaiting_ack_since_ms = now;
   211	          events |= AG_EVENT_SEDENTARY_ALERT;
   212	        }
   213	    }
   214	  else if (state->present)
   215	    {
   216	      if (state->absence_since_ms == 0)
   217	        {
   218	          state->absence_since_ms = now;
   219	        }
   220	
   221	      if (ag_elapsed(now, state->absence_since_ms, config->break_confirm_ms))
   222	        {
   223	          state->present = false;
   224	          state->presence_since_ms = 0;
   225	          state->poor_posture_since_ms = 0;
   226	          state->sedentary_alerted = false;
   227	          state->posture_alerted = false;
   228	          state->awaiting_ack = false;
   229	          state->lock_sent = false;
   230	          events |= AG_EVENT_BREAK_STARTED;
   231	        }
   232	    }
   233	
   234	  if (state->privacy_enabled && observation->face_count > 1)
   235	    {
   236	      if (!state->privacy_blurred)
   237	        {
   238	          state->privacy_blurred = true;
   239	          events |= AG_EVENT_BLUR_SCREEN;
   240	        }
   241	    }
   242	  else if (state->privacy_blurred)
   243	    {
   244	      state->privacy_blurred = false;
   245	      events |= AG_EVENT_UNBLUR_SCREEN;
   246	    }
   247	
   248	  if (!state->lock_sent && config->lock_after_unanswered_reminder &&
   249	      state->awaiting_ack &&
   250	      ag_elapsed(now, state->awaiting_ack_since_ms,
   251	                 config->reminder_grace_ms))
   252	    {
   253	      state->lock_sent = true;
   254	      state->awaiting_ack = false;
   255	      events |= AG_EVENT_LOCK_SCREEN;
   256	    }
   257	
   258	  if (!state->lock_sent && config->lock_when_privacy_user_leaves &&
   259	      state->privacy_enabled && !has_face && state->absence_since_ms != 0 &&
   260	      ag_elapsed(now, state->absence_since_ms,
   261	                 config->privacy_absence_lock_ms))
   262	    {
   263	      state->lock_sent = true;
   264	      events |= AG_EVENT_LOCK_SCREEN;
   265	    }
   266	
   267	  return events;
   268	}
