    72	        state->awaiting_ack = false;
    73	        state->sedentary_alerted = false;
    74	        state->lock_sent = false;
    75	        events |= AG_EVENT_ACKNOWLEDGED;
    76	        break;
    77	
    78	      case AG_COMMAND_PAUSE:
    79	        if (!state->reminders_paused)
